   let productamout=handleqty(id)*price
    amount +=productamout
    return productamout

 }

function handlin(e,id,qty){
    let currentqty=handleqty(id)
    //alert(qty)
    //alert(currentqty)
    if(currentqty==qty){
        //alert(qty)
        alert(`${currentqty} quantity   is avalible in stock`)
        return
    }
    let _cart={...cart}
    _cart.item[id]=currentqty+1
    _cart.totalItems +=1
    setCart(_cart)

  }





  function handlout(e,id){
    let currentqty=handleqty(id)
    if(currentqty===1){
        return
    }
    let _cart={...cart}
    _cart.item[id]=currentqty-1
    _cart.totalItems -=1
    setCart(_cart)

  }
  function handledelete(e,id){
   let currentqty=handleqty(id)
   //alert(currentqty)
