                            <td><h4>Total Amount:{amount}</h4></td>
                          
                                </tr>
                             <tr>  <td colSpan="5"><button className="btn btn-info form-control" onClick={(e)=>{handlecachout(e)}}> check out</button></td></tr>


                            </tbody>
                        </tabel >
                    </div>
                </div>
            </div>
        
        </section>
          :<img src="emptycart.png"  style={{width:'100%',height:'400px'}} alt=""/>}
       </>
    );
}

export default Cart;
